import java.util.stream.*;

public class Main {
    public static void main(String[] args) throws Exception {
        List<String> masukan = List.of("  kopi susu ", "", "   ", "teh");
        List<String> bersih = masukan.stream()
                .map(String::strip)
                .filter(s -> !s.isBlank())
                .toList();
        System.out.println(bersih);
        System.out.println("=".repeat(20));
        System.out.println("%-10s|%8d".formatted("Kopi", 18000));
        for (int jumlah : new int[]{-2, 5, 50}) {
            System.out.println("Pesan " + jumlah + " -> " + Math.clamp(jumlah, 1, 10));
